"""Publish already verified spent-cohort age-information BTC accounts; never rerun research."""
import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-dormancy-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==72 and rep['all_bytes_equal'] and rep['matched_files']==121 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('DA_INFO','DA_FLOW','DA_AGE','DA_PRICE','DA_INV','DA_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='DA_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('DA_FLOW','DA_AGE','DA_PRICE','DA_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['constraint_weeks']])
 evidence={'build':'1003a1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development, raw spent-cohort age beyond spent volume and price; current vintage first published July2026, earlier periods retrospective reconstruction; D+6 assumed availability, not actual full historical publication; not independent chain reconstruction or identified selling; no accepted strategy'}
 (DOWN/'btc-dormancy-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-dormancy-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-dormancy-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_dormancy_study.py','test_btc_dormancy_study.py','verify_btc_dormancy_study.py','reproduce_btc_dormancy_study.py','audit_btc_dormancy_data.py','collect_btc_dormancy_data.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  folder=ROOT/'data/btc-dormancy-20261003'
  for p in sorted(folder.rglob('*')):
   if p.is_file():files.append((p,'input/'+str(p.relative_to(folder))))
  web=ROOT/'data/btc-web-20261003';raw=web/'q118-aggregate-probes'
  for p in sorted(raw.glob('*.csv')):files.append((p,'input/obm/'+p.name))
  for p in sorted(web.glob('q118-dormancy-*.csv')):files.append((p,'input/obm-clock/'+p.name))
  for n in ('q118-quality-audit.json','q118-dormancy-history.json','q118-clock-audit-fetch-meta.json','q118-clock-meta.json','q118-details-meta.json','q118-aggregate-probe-meta.json','q118-zenodo.json','q118-data-license.md'):files.append((web/n,'references/'+n))
  files.extend([(ROOT/'data/btc-mining-20261002/n-transactions.json','input/blockchain-transactions-reused.json'),(ROOT/'data/btc-venue-20261003/masks.json','input/btc-no-trade-mask.json'),(DOC/'EXPERIMENT_BTC_DORMANCY_20261003.md','source/EXPERIMENT_BTC_DORMANCY_20261003.md')])
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),'''All 72 accounts, weekly features/forecasts, five current OBM CSVs, five archived-release CSV subsets, four additional commit-clock snapshots, reused public Blockchain.com daily BTC transaction-count chart, normalization/masks and independent audit are included. No individual address, wallet or transaction queries. Original full Zenodo archive (SHA/MD5 supplied), CM diagnostic CSV, raw BTC market ZIPs/checksums/normalized market, original repository layout and common Python dependencies remain separate reproduction inputs. This evidence ZIP is not a standalone full environment. No paper PDFs, provider node/RPC code, live trading or private data.
OBM data/documentation: Diego R. Llanos, Open Bitcoin Metrics: Verifiable Full-Node-Derived Bitcoin Time Series for Economic Research (2026), https://arxiv.org/abs/2607.03124 ; archived release https://doi.org/10.5281/zenodo.21156871 ; current commit ab99e2609a257dfc0e1e4c7ec21708930909ec19 at https://github.com/diegorllanos/open-bitcoin-metrics ; data CC BY 4.0 https://creativecommons.org/licenses/by/4.0/ . Original aggregate CSVs unchanged; normalized JSON, validity masks, weekly ratios and forecasts are our transformations, not author-endorsed. Data license text included. Blockchain.com and Binance sources are separate providers, not relabeled as OBM CC BY data.
Current historical snapshots do not establish first-release vintages. OBM first public July2026; earlier performance is retrospective development reconstruction only. Six-day publication lag is an assumption supported by limited 2026 snapshots. Aggregate checks do not independently reconstruct spent outputs or identify selling.
''')
 html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 이동 물량 연령 정보 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003a1</p><h1>오래 보유한 BTC의 이동도<br>쓸 만한 추가 예측으로 이어지지 않았습니다.</h1><p class="lead">이동한 BTC의 평균 연령을 이동량·가격 변화와 분리했습니다. 기본 후보는 최근 손실과 낙폭, 가격 대조보다 큰 예측오차로 기각됐습니다. 이 집계가 실제 매도를 식별하는 것은 아닙니다.</p><div class="facts"><article><b>72</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>DA_INFO 기본 후보</span></article><article><b>121</b><span>파일 소켓차단 바이트 일치</span></article></div><p class="boundary">2022–2025와 2026.01–08은 이미 본 개발 자료입니다. OBM 첫 공개는 2026.07이므로 이전 기간은 당시 배포된 CSV로 수행한 거래가 아니라 역사 재구성입니다. 새 OOS·실전·실제 매도자 식별이 아닙니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT. 수익과 최대낙폭(DD)은 %. TREND는 기존 E_SPOT의 일별·주요회계와 같습니다.</p>'''+table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')+'''<p>기본 주 +43.40%·DD21.54%·연변동성15.48%·Sharpe0.659, 최근 −9.68%·DD12.10%. 주 수익52.838713%·DD13.561952%·변동성13.343621%·Sharpe0.8과 최근 수익4.628391%·DD10.450946%의 기존 관문을 유지했습니다. 2023년도 −2.02%였습니다.</p><p>반대 DA_INV의 최근 +12.93%를 보고 기본으로 바꾸지 않았습니다. 이 대조는 주 +23.34%·DD30.71%로 전체 기준을 충족하지 않습니다. FLOW·AGE·PRICE 등 유리한 비교군이나 위험 조건을 사후 승격하지 않습니다.</p></section><section><h2>전체 보유량이 아닌, 이동한 물량의 연령</h2><p>일별 CDD는 소비된 BTC×그 물량의 이전 보유일수 합입니다. 이것을 이동 BTC 합으로 나눈 값은 이동 코호트의 가중 평균 연령입니다. 전체 BTC 재고의 평균 보유기간·통화속도·거래소 매도량·소유자 수와 다릅니다.</p><p>가까운7일의 CDD합/이동량합과 그 앞28일의 비율을 비교했습니다. 일별 연령의 단순 평균이 아닙니다. log(1+연령)의 변화와 평균 이동량의 로그변화를 분리하여, 이동량과 가격을 넘어 연령 구성이 다음 주 BTC 수익에 정보를 주는지 검사했습니다. 창·문턱·부호를 결과 뒤 바꾸지 않았습니다.</p><p>자기전송·change·수탁 지갑 재편과 오프체인 거래 때문에 오래된 물량의 이동을 곧바로 매도로 볼 수 없습니다. Smith2018 원문의 가격 그림·선택 하위표본 상관도 미래 순수익 증거가 아닙니다. 원문 추정거래량과 이번 raw spent value는 정의가 달라 논문 복제라고 하지 않습니다.</p></section><section><h2>공개 시계를 확인하고 불일치는 보존했습니다</h2><p>OBM의 정확한2026-10-03 commit에서 공개 BTC 일별집계5CSV를 동결했습니다. 초기 Zenodo 배포와 현재의 중복31,938행은 모두 같고, 원본 아카이브 MD5도 메타와 일치했습니다. 하지만 같은 버전명0.1.0은 매일 바뀌는 파일의 빈티지를 증명하지 않습니다.</p><p>최근5개commit과 첫July3배포는 모두 게시일−5일까지 제공했습니다. 일D의 기본 가용을 D+6일00UTC로 고정하고 추가7일 지연도 검정했습니다. 이 소수 시점이 전체 과거의 실제 배포 시각·불변 자료를 보증하지 않습니다. 첫 공개 이전 역사 결과는 재구성 탐색입니다.</p><p>2020.01–2026.08의2,435일 중2,410일만 유효합니다. 기존 Blockchain.com 일별 거래건수와 다른22일은 인접11쌍의 이틀 합이 같았지만 원인이 확정되지 않아 전부 무효로 두었습니다. 외부누락3일도 채우지 않았습니다.35일 중 하루라도 무효이면 모든 모형이 같은 행을 제외합니다. 기본 주147일·최근49일은 자료/모형 무효로 가격 추세에 복귀했습니다.</p><p>CoinMetrics 블록수는2,700일 모두 같지만 거래건수 차이는 Coinbase 보상거래 제외만으로 설명되지 않았습니다. 차이가 해결됐다고 하지 않고 분모를 섞지 않았습니다. 같은 OBM의 CDD/이동량=dormancy 항등식 통과도 독립 체인 검증이 아닙니다. 개인 주소·지갑·개별 거래·전체노드 조회는 하지 않았습니다.</p></section><section><h2>연령의 추가 예측력과 비용 이후 계좌</h2><p>월요일마다104달력주 안에서 완료된 다음7일 목표를 학습합니다. 최소52공통유효주·최근1주 분리·달력1주 HAC. INFO는 가격7/28일+이동량+연령, FLOW·AGE는 각각 한 온체인 성분, PRICE는 가격만 사용했습니다. 계수 부호는 과거 자료로만 정하고, 양수·음수 모두 허용했습니다.</p><p>INFO 예측이 비용+한 표준오차를 넘고 FLOW 대비 추가분이 같은 방향일 때만 기존 추세를 바꿉니다. 반대 대조는 같은 발동 주를 사용합니다. 기본 발동은 주54주374일·최근4주25일로 계좌 경계의 부분 주도 포함합니다. 방향은 주간 고정, 위험량만 매일 갱신합니다.</p><p>공통 예측은 주187개·최근27개. 주 MSE INFO0.005156236, FLOW0.005179819, PRICE0.004956423; 최근 INFO0.003645356, FLOW0.003600683, PRICE0.003597078. 주 FLOW 대비 작은 개선만으로 가격 대조 열위와 최근 악화를 무시하지 않았습니다.</p><p>기본 비용2배 +35.34% / −10.23%, 추가1h 실행 +40.24% / −9.47%, 추가24h +22.60% / −9.65%, 자료7일 추가지연 +36.84% / −0.63%. 모든 지연·비용 조건에서 최근 순익이 음수였습니다.</p><details><summary>예측과 자료지연</summary>'''+table(['기간','추가지연(일)','모형','공통주','MSE','방향정확도%','부호제약주'],forecast,'forecast-results')+'</details><details><summary>연도별 수익</summary>'+table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')+'</details><details><summary>롱숏·비용·펀딩·위험</summary>'+table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')+'</details><details><summary>모든 대조군 차이의 불확실성</summary><p>14일 원형블록2,000회95%구간(%/일);7/28일은 JSON. 반복개발·자료 빈티지 문제를 해소하는 독립 입증이 아닙니다.</p>'+table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')+'</details></section><section><h2>모든 비용·지연·위험 조건</h2><p>현물10bp/선물5bp 수수료+각1.5bp 불리한 impact, 실제 funding, 수량·금액 최소치·5%p 조절밴드·종료비용 포함. 위험목표20%/진입 명목상한1배, 비용2배·추가1/24h 실행·위험10%·추가7일 자료지연을 보존했습니다. 실제호가·부분체결·과거규정·순간청산·세금·운영비는 완전히 복원하지 못했습니다.</p><details id="matrix"><summary>72계좌 전체 보기</summary>'+table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts')+'</details></section>'
